def pic(src,title):
    return f'<figure><button class="photo" data-src="{src}" data-title="{title}" aria-label="放大：{title}"><img src="{src}" alt="{title}" loading="lazy"></button><figcaption>{title}</figcaption></figure>'
def asset(name,title):return pic('assets/'+name,title)
def shot(name,title):return pic('evidence/'+name,title)
def guide_shot(name,title):return shot(name,title).replace('loading="lazy"','loading="eager"')
